import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup } from '@angular/forms';
import { Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';

@Component({
  selector: 'app-profile',
  templateUrl: './profile.page.html',
  styleUrls: ['./profile.page.scss'],
})
export class ProfilePage implements OnInit {
  ambastorListData: any[];
  form: FormGroup;

  constructor(
    private userService: UserService,
    private router: Router 
  ) { }

  ngOnInit() {
    this.initialValidator()
  }

  ionViewDidEnter() {
    this.getServerData()
  } 

  getServerData() {
    this.ambastorListData = []
    this.userService.profileDetail().subscribe((response) => {
     this.ambastorListData = response.result
     this.form.patchValue(this.ambastorListData[0])
    }) 
  }

  initialValidator() {
    this.form = new FormGroup({
      IndxId: new FormControl('',null),
      AccHolderName: new FormControl('',null),
      AccNo: new FormControl('',null),
      AmbastorId: new FormControl('',null),
      Branch: new FormControl('',null),
      Email: new FormControl('',null),
      IfscCode: new FormControl('',null),
      Name: new FormControl('',null),
      PhoneNo: new FormControl('',null),
      Status: new FormControl('',null),
    })
  }

  navigateBack() {
    this.router.navigate(['/tabs/stem-dashboard']); 
  }

  onEdit() {
    this.form.controls['Status'].setValue('1');
    this.form.controls['Status'].updateValueAndValidity();

    let data =  { "records" : this.form.value } 
    
    this.userService.editAmbastor(data).subscribe((response) => {
    this.router.navigate(['/tabs/stem-dashboard']);  
     }) 
  } 

}
